func (a *App) service(d Obj)Obj { o,_:=d["origin"].(map[string]any);lat,lon:=asFloat(o["latitude"]),asFloat(o["longitude"]);st:=asStr(d["sampleTypeId"]);nodes:=[]any{}; labs:=[]any{}; for _,l:=range a.s.Locations {fs,_:=l["functions"].(map[string]any);if !asBool(l["active"]){continue}; co,_:=l["coordinate"].(map[string]any); if asBool(fs["collection_point"]) && distance(lat,lon,asFloat(co["latitude"]),asFloat(co["longitude"]))<=asFloat(l["coverageKm"]){nodes=append(nodes,l["locationId"])};if asBool(fs["laboratory"]) {acc,_:=l["acceptedSampleTypeIds"].([]any);for _,x:=range acc{if asStr(x)==st{labs=append(labs,l["locationId"]);break}}} }; serviceable:=len(nodes)>0&&len(labs)>0; reason:="";if !serviceable{reason="No active collection point or accepting laboratory is reachable"};state:="unserviceable";if serviceable{state="serviceable"};return Obj{"serviceable":serviceable,"reason":reason,"serviceability":state,"snapshotVersion":1,"candidateCollectionPointIds":nodes,"candidateLaboratoryIds":labs,"estimatedDeliveryAt":d["deliveryDeadline"]} }

