func id() string { b:=make([]byte,16); rand.Read(b); return fmt.Sprintf("%s-%s-4%s-%x-%s",hex.EncodeToString(b[:4]),hex.EncodeToString(b[4:6]),hex.EncodeToString(b[6:8])[:3],b[8]&0x3f|0x80,hex.EncodeToString(b[9:])) }
