func timeline(s Obj)[]any { x,_:=s["timeline"].([]any);return x }; func addEvent(s Obj,action string,u Obj){ t:=timeline(s);t=append(t,Obj{"eventId":len(t)+1,"action":action,"actorId":u["userId"],"role":u["activeRole"],"entityType":"sample","entityId":s["sampleId"],"success":true,"occurredAt":now(),"details":Obj{}});s["timeline"]=t }
