 case p=="/api/create-user":
  if !admin(){return};if !req(d,"username","initialPassword","roles","active"){err(w,400,"missing required fields");return};for _,x:=range a.s.Users{if asStr(x["username"])==asStr(d["username"]){err(w,409,"username already exists");return}};x:=Obj{"userId":id(),"username":d["username"],"password":d["initialPassword"],"roles":d["roles"],"active":d["active"],"fullName":d["fullName"],"email":d["email"],"phone":d["phone"],"qualifications":orArr(d["qualifications"]),"certifications":orArr(d["certifications"]),"assignedLocationId":d["assignedLocationId"],"available":true};a.s.Users[asStr(x["userId"])]=x;a.audit(u,"create_user","user",asStr(x["userId"]),true,d);a.save();write(w,201,Obj{"data":a.publicUser(x)})
 case p=="/api/update-user-access":
