func distance(a1,b1,a2,b2 float64)float64{p:=math.Pi/180; x:=math.Sin((a2-a1)*p/2)*math.Sin((a2-a1)*p/2)+math.Cos(a1*p)*math.Cos(a2*p)*math.Sin((b2-b1)*p/2)*math.Sin((b2-b1)*p/2);return 6371*2*math.Atan2(math.Sqrt(x),math.Sqrt(1-x))}
func (a *App) service(d Obj)Obj { o:=asObj(d["origin"]);lat,lon:=asFloat(o["latitude"]),asFloat(o["longitude"]);st:=asStr(d["sampleTypeId"]);nodes:=[]any{}; labs:=[]any{}; for _,l:=range a.s.Locations {fs:=asObj(l["functions"]);if !asBool(l["active"]){continue}; co:=asObj(l["coordinate"]); if asBool(fs["collection_point"]) && distance(lat,lon,asFloat(co["latitude"]),asFloat(co["longitude"]))<=asFloat(l["coverageKm"]){nodes=append(nodes,l["locationId"])};if asBool(fs["laboratory"]) {acc:=orArr(l["acceptedSampleTypeIds"]);for _,x:=range acc{if asStr(x)==st{labs=append(labs,l["locationId"]);break}}} }; serviceable:=len(nodes)>0&&len(labs)>0; reason:="";if !serviceable{reason="No active collection point or accepting laboratory is reachable"};state:="unserviceable";if serviceable{state="serviceable"};return Obj{"serviceable":serviceable,"reason":reason,"serviceability":state,"snapshotVersion":1,"candidateCollectionPointIds":nodes,"candidateLaboratoryIds":labs,"estimatedDeliveryAt":d["deliveryDeadline"]} }

